    if not marker_cells:
        return out
    marker_color = Counter(grid[r][c] for r, c in marker_cells).most_common(1)[0][0]

    # Select the bar whose longitudinal span contains the most markers.
    def along(seg, cell):
        return cell[1] if seg[0] in ('top', 'bottom') else cell[0]
    def span(seg):
        return seg[2], seg[3]
    source = max((first, second), key=lambda seg: sum(span(seg)[0] <= along(seg, cell) < span(seg)[1] for cell in marker_cells))
    target = second if source is first else first
    sr0, sr1 = span(source)
    offsets = sorted({along(source, cell) - sr0 for cell in marker_cells if sr0 <= along(source, cell) < sr1})
    if not offsets:
        return out
    tr0, _ = span(target)

    # From the marked side, draw from its bar only as far as each marker.
    for r, c in marker_cells:
        if source[0] in ('top', 'bottom') and sr0 <= c < sr1:
            wall_r = source[1]
            step = 1 if source[0] == 'top' else -1
            rr = wall_r + step
            while 0 <= rr < h and rr != r:
                out[rr][c] = marker_color
                rr += step
        elif source[0] in ('left', 'right') and sr0 <= r < sr1:
            wall_c = source[1]
            step = 1 if source[0] == 'left' else -1
            cc = wall_c + step
            while 0 <= cc < w and cc != c:
                out[r][cc] = marker_color
                cc += step

    # The opposite bar carries the full rays at the same offsets.
    for off in offsets:
        if target[0] in ('top', 'bottom'):
            c = tr0 + off
            rows = range(0, h - 1) if target[0] == 'bottom' else range(1, h)
            for r in rows:
                out[r][c] = marker_color
        else:
            r = tr0 + off
            cols = range(0, w - 1) if target[0] == 'right' else range(1, w)
            for c in cols:
                out[r][c] = marker_color
    for r, c in marker_cells:
        out[r][c] = 4
    return out
